let input = $json.body ?? $json;
if (typeof input === 'string') { try { input = JSON.parse(input); } catch { input = {}; } }
const background = typeof input.background === 'string' ? input.background.trim() : '';
if (background.length < 20 || background.length > 2500) return [{json:{ok:false,statusCode:400,error:'A scene Background description between 20 and 2,500 characters is required.'}}];
const prompt = [
  'Create one landscape 16:9 static environmental background plate for one scene in Fred’s educational animation series.',
  'Use the attached image only as a style reference: consistent hand-drawn 2D art, bold slightly irregular black ink outlines, chunky simplified shapes, flat color blocks, and restrained cel shading. Avoid photorealism and 3D.',
  'Design the location, palette, and composition specifically for the supplied storyboard Background. The reference image is not a location template: do not copy its living room, sofa, plant, colors, or framing unless the scene calls for them.',
  'Show only the environment. Do not draw people, characters, faces, bodies, hands, human-like silhouettes, animals, focal subjects, diagrams, arrows, symbols, labels, captions, letters, logos, watermarks, or motion marks.',
  'Fixed architecture and environmental fixtures or furnishings may establish the place; omit loose foreground props because animators draw those separately.',
  'Keep a broad, readable background with clear depth and open space for animators to add hand-drawn characters, props, text, and motion.',
  'SCENE-SPECIFIC BACKGROUND SETTING: ' + background
].join(' ');
const sceneNumbers = Array.isArray(input.sceneNumbers) ? input.sceneNumbers.map(Number).filter(Number.isFinite) : [];
return [{json:{ok:true,fileId:'19_rZZhpt3du495njrjnO5nuPWQjxnMAQ',backgroundId:String(input.backgroundId || ''),sceneNumbers,prompt}}];

const files = $input.all();
const request = $('Prepare Image Request').first().json;
if (!request.ok || files.length !== 1) throw new Error('Exactly one approved environment reference is required.');
const binary = files[0].binary?.data;
if (!binary) throw new Error('The Google Drive environment reference did not download as an image.');
const buffer = await this.helpers.getBinaryDataBuffer(0,'data');
const mimeType = binary.mimeType || 'image/png';
if (!mimeType.startsWith('image/')) throw new Error('The environment style reference is not an image file.');
const inputReference = {type:'image_url',image_url:{url:'data:'+mimeType+';base64,'+buffer.toString('base64')}};
return [{json:{model:'openai/gpt-image-2.5-flare',prompt:request.prompt,n:1,aspect_ratio:'16:9',quality:'low',input_references:[inputReference]}}];

const response = $json ?? {};
const body = response.body && typeof response.body === 'object' ? response.body : response;
const image = body.data?.[0];
const b64 = image?.b64_json;
const request = $('Prepare Image Request').first().json;
const identity = {backgroundId:request.backgroundId,sceneNumbers:request.sceneNumbers};
if (!b64) {
  const providerError = body.error;
  const errorMessage = typeof providerError === 'string' ? providerError : providerError?.message || response.error?.message || body.message || 'OpenRouter did not return image bytes.';
  const statusCode = Number(response.statusCode || providerError?.code || 502);
  return [{json:{ok:false,statusCode,error:String(errorMessage).slice(0,1200),model:'openai/gpt-image-2.5-flare',...identity}}];
}
const mimeType = image.media_type || body.media_type || 'image/jpeg';
if (!mimeType.startsWith('image/')) throw new Error('The provider returned an unsupported media type.');
return [{json:{ok:true,model:'openai/gpt-image-2.5-flare',...identity,mimeType,costUsd:body.usage?.cost ?? null,imageData:'data:'+mimeType+';base64,'+b64}}];

let body = $json.body ?? $json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};
const action = body.action === 'plan' ? 'plan' : body.action === 'image' ? 'image' : 'invalid';
return [{json:{...body,action}}];

let body = $json.body ?? $json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const script = typeof body.script === 'string' ? body.script.trim() : '';
if (script.length < 20 || script.length > 30000) return [{json:{ok:false,statusCode:400,error:'Paste a script between 20 and 30,000 characters.'}}];
const firstLine = script.split(/\r?\n/).map(part => part.trim()).find(Boolean) || '';
const title = String(body.title || firstLine.slice(0,120) || 'Untitled storyboard').trim().slice(0,120);
return [{json:{ok:true,title,script}}];

const req = $('Validate Full Script').first().json;
const rows = $('Read Planner Context').all().map(item => item.json);
const grouped = { styleGuide: [], referenceIndex: [], examples01: [], examples03: [] };

for (const row of rows) {
  const type = String(row.recordType || '');
  const raw = row.payloadJson;
  let payload;
  try { payload = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { continue; }
  if (!payload || typeof payload !== 'object') continue;
  if (type === 'style_guide') grouped.styleGuide.push(payload);
  else if (type === 'reference_index') grouped.referenceIndex.push(payload);
  else if (type === 'example_01') grouped.examples01.push(payload);
  else if (type === 'example_03') grouped.examples03.push(payload);
}

const stopWords = new Set(['about','after','again','also','because','been','being','could','does','from','have','into','just','more','most','that','their','them','then','there','these','they','this','those','through','very','what','when','where','which','while','with','would','your']);
const terms = new Set((req.script.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []).filter(word => word.length > 3 && !stopWords.has(word)));
const rank = sourceRows => sourceRows.map((row, index) => {
  const text = JSON.stringify(row).toLowerCase();
  let score = 0;
  for (const term of terms) if (text.includes(term)) score += 1;
  return { row, score, index };
}).sort((a, b) => b.score - a.score || a.index - b.index).slice(0, 4).map(item => item.row);

const environmentReferences = grouped.referenceIndex.filter(row => String(row.referenceType || '').toLowerCase() === 'environment').slice(0, 2);
return [{ json: {
  title: req.title,
  script: req.script,
  styleGuide: grouped.styleGuide,
  referenceIndex: environmentReferences.length ? environmentReferences : grouped.referenceIndex.slice(0, 1),
  examples01: rank(grouped.examples01),
  examples03: rank(grouped.examples03)
} }];

const fail = (error, statusCode = 422) => [{ json: { ok: false, statusCode, error } }];
const raw = $json.output ?? $json;
let plan;
try { plan = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { return fail('The storyboard model returned invalid structured data. No background images were generated.', 502); }
if (!Array.isArray(plan?.scenes) || !plan.scenes.length) return fail('The storyboard model returned no scenes. No background images were generated.', 502);

const request = $('Validate Full Script').first().json;
const stripTimecodes = value => String(value || '').replace(/\b\d{1,2}:\d{2}(?::\d{2})?(?:\s*[-–—]\s*\d{1,2}:\d{2}(?::\d{2})?)?\b/g, ' ');
const tokens = value => String(value || '').normalize('NFKC').toLowerCase().match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu) || [];
const sourceTokens = tokens(stripTimecodes(request.script));
const voiceoverTokens = tokens(plan.scenes.map(scene => String(scene?.voiceover || '')).join(' '));
const isComplete = sourceTokens.length === voiceoverTokens.length && sourceTokens.every((token, index) => token === voiceoverTokens[index]);
if (!isComplete) return fail('The storyboard did not preserve the complete script in order. No background images were generated; retry the storyboard. The submitted script was not truncated.');

const sourceHasTimecodes = /\b\d{1,2}:\d{2}(?::\d{2})?\b/.test(request.script);
const unique = new Map();
for (let index = 0; index < plan.scenes.length; index++) {
  const scene = plan.scenes[index] || {};
  const description = String(scene.background || '').trim();
  if (description.length < 20) return fail('Scene ' + (index + 1) + ' is missing a useful Background description. No images were generated.');
  const key = description.toLowerCase().replace(/\s+/g, ' ');
  if (!unique.has(key)) unique.set(key, { backgroundPrompt: description, sceneNumbers: [] });
  const sceneNumber = Number(scene.sceneNumber);
  unique.get(key).sceneNumbers.push(Number.isInteger(sceneNumber) && sceneNumber > 0 ? sceneNumber : index + 1);
}

const all = Array.from(unique.values());
const limit = 10;
const selected = all.length <= limit ? all : Array.from({ length: limit }, (_, slot) => all[Math.floor((slot + 0.5) * all.length / limit)]);
const deferredBackgrounds = Math.max(0, all.length - selected.length);
const backgrounds = selected.map((item, index) => ({
  backgroundId: 'BG' + String(index + 1).padStart(3, '0'),
  sceneNumbers: item.sceneNumbers,
  backgroundPrompt: item.backgroundPrompt
}));
const columns = [
  ['Scene', 'sceneNumber'],
  ['Timestamp', 'timestamp'],
  ['Voiceover', 'voiceover'],
  ["What's happening", 'whatsHappening'],
  ['Background', 'background'],
  ['Hand-drawn characters & props', 'handDrawnCharactersAndProps'],
  ['On-screen text', 'onScreenText'],
  ['Transitions/Motion', 'transitionsMotion']
];
const csvCell = value => '"' + String(value ?? '').replace(/"/g, '""') + '"';
const storyboardCsv = [
  columns.map(([header]) => csvCell(header)).join(','),
  ...plan.scenes.map(scene => columns.map(([, key]) => csvCell(key === 'timestamp' && !sourceHasTimecodes ? '' : scene?.[key])).join(','))
].join('\r\n');

return [{ json: {
  ok: true,
  totalScenes: plan.scenes.length,
  totalUniqueBackgrounds: all.length,
  generatedBackgroundLimit: limit,
  deferredBackgrounds,
  scriptWordCount: sourceTokens.length,
  note: deferredBackgrounds
    ? 'The complete storyboard is ready. Up to ' + limit + ' representative unique backgrounds sampled across the script are included; ' + deferredBackgrounds + ' remain for a later batch.'
    : 'The complete storyboard is ready. Every unique background is included in this image batch.',
  storyboardCsv,
  backgrounds
} }];
